inline int64_t xck_cmgga_tau_r_o2_batch_work(int64_t npts, int64_t nbf, int64_t nx) {
    const int64_t blk = npts < grid_block ? npts : grid_block;
    const int64_t nxc = nx < 8 ? nx : 8;
    return blk * (81 + nbf * (nxc + 0)) + 0 * npts + 1;
}

